draw(q--a--b);
//draw(a--t);
draw(a--c--b);

label("$Q(0, 12)$", q, W);
label("$A(2, 12)$", a, NE);
label("$B(12, 0)$", b, S);
label("$O(0, 0)$", o, SW);
label("$x$", (15, 0), E);
label("$y$", (0, 15), N);
//label("$T(2, 0)$", t, S + 0.6 * E);
label("$C(0, p)$", c, W);
